#!/usr/bin/env python3
"""PreToolUse hook (matcher: Bash): refuse git commands that skip git hooks."""

import json
import shlex
import sys

OPERATORS = {";", "&&", "||", "|", "&", "(", ")"}


def segments(command: str) -> list[list[str]]:
    lexer = shlex.shlex(command, posix=True, punctuation_chars=True)
    lexer.whitespace_split = True
    result: list[list[str]] = [[]]
    for token in lexer:
        if token in OPERATORS:
            result.append([])
        else:
            result[-1].append(token)
    return [segment for segment in result if segment]


def skips_hooks(tokens: list[str]) -> bool:
    if "git" not in tokens:
        return False
    after_git = tokens[tokens.index("git") + 1 :]
    if "--no-verify" in after_git:
        return True
    if "commit" in after_git:
        short_flags = [
            t for t in after_git if t.startswith("-") and not t.startswith("--")
        ]
        return any("n" in flag[1:] for flag in short_flags if not flag.startswith("-m"))
    return False


def main() -> int:
    command = json.load(sys.stdin).get("tool_input", {}).get("command", "")
    try:
        found = any(skips_hooks(s) for s in segments(command))
    except ValueError:
        found = "--no-verify" in command
    if found:
        print(
            "Blocked: this command would skip git hooks (--no-verify or "
            "commit -n). Fix the failing hook instead, or ask Rod.",
            file=sys.stderr,
        )
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())

